doppler-effect-moving-source-observer-ca.js:
(() => {
  'use strict';
  const f0El = document.getElementById('dop-f0'), vsEl = document.getElementById('dop-vs'), dirEl = document.getElementById('dop-dir');
  const fResEl = document.getElementById('dop-res-f'), pResEl = document.getElementById('dop-res-pitch');

  const c_sound = 343.0; // m / s in 20°C air

  function update() {
    const f0 = parseFloat(f0El.value), vsKmh = parseFloat(vsEl.value);
    const mode = dirEl.value;

    if (isNaN(f0) || isNaN(vsKmh) || f0 <= 0 || vsKmh < 0) return;

    const vsMs = vsKmh / 3.6;
    if (vsMs >= c_sound) {
      fResEl.textContent = 'Sonic Boom Mach Wave (v_s ≥ 343 m/s)';
      pResEl.textContent = 'Source moving at supersonic speed (Mach ' + (vsMs / c_sound).toFixed(2) + ')';
      return;
    }

    // Approaching: f_app = f0 * ( c / (c - vs) )
    const f_app = f0 * (c_sound / (c_sound - vsMs));
    // Receding: f_rec = f0 * ( c / (c + vs) )
    const f_rec = f0 * (c_sound / (c_sound + vsMs));

    const fObs = mode === 'approaching' ? f_app : f_rec;
    const shiftHz = fObs - f0;

    // Musical semitone shift = 12 * log2(fObs / f0)
    const semitones = 12 * Math.log2(fObs / f0);

    fResEl.textContent = 'f' = ' + fObs.toFixed(1) + ' Hz (' + (shiftHz >= 0 ? '+' : '') + shiftHz.toFixed(1) + ' Hz Shift)';
    pResEl.textContent = 'Pitch Shift: ' + (semitones >= 0 ? '+' : '') + semitones.toFixed(2) + ' Semitones | Approaching: ' + f_app.toFixed(1) + ' Hz, Receding: ' + f_rec.toFixed(1) + ' Hz';
  }

  [f0El, vsEl].forEach(el => el.addEventListener('input', update));
  dirEl.addEventListener('change', update);
  update();
})();

doppler-effect-sound-frequency-shift-mov.js:
(() => {
  'use strict';
  const f0El = document.getElementById('dp-f0'), vsEl = document.getElementById('dp-vs');
  const motEl = document.getElementById('dp-motion'), vEl = document.getElementById('dp-vsound');
  const fpResEl = document.getElementById('dp-res-fprime'), rcResEl = document.getElementById('dp-res-recede');

  function update() {
    const f0 = parseFloat(f0El.value), vs = parseFloat(vsEl.value);
    const isApproach = motEl.value === 'approach', v = parseFloat(vEl.value);

    if (isNaN(f0) || isNaN(vs) || isNaN(v) || f0 <= 0 || vs < 0 || v <= vs) return;

    // Approaching source: f_app = f0 * ( v / (v - vs) )
    const f_app = f0 * (v / (v - vs));
    // Receding source: f_rec = f0 * ( v / (v + vs) )
    const f_rec = f0 * (v / (v + vs));

    const current_f = isApproach ? f_app : f_rec;
    const diff = current_f - f0;
    const drop = f_app - f_rec;

    fpResEl.textContent = 'f' = ' + current_f.toFixed(2) + ' Hz (' + (diff >= 0 ? '+' : '') + diff.toFixed(2) + ' Hz Shift)';
    rcResEl.textContent = (isApproach ? 'When Receding: f' = ' + f_rec.toFixed(2) + ' Hz' : 'When Approaching: f' = ' + f_app.toFixed(2) + ' Hz') + ' | Total Pass Drop = ' + drop.toFixed(2) + ' Hz (Mach ' + (vs/v).toFixed(2) + ')';
  }

  [f0El, vsEl, vEl].forEach(el => el.addEventListener('input', update));
  motEl.addEventListener('change', update);
  update();
})();

doppler-redshift-calculator.js:
(() => {
  'use strict';
  const emitEl = document.getElementById('rs-emit'), obsEl = document.getElementById('rs-obs');
  const zEl = document.getElementById('rs-res-z'), velEl = document.getElementById('rs-res-vel'), cPctEl = document.getElementById('rs-res-c-pct');

  const c = 299792.458; // km/s

  function update() {
    const lambda0 = parseFloat(emitEl.value);
    const lambdaObs = parseFloat(obsEl.value);
    if (isNaN(lambda0) || isNaN(lambdaObs) || lambda0 <= 0 || lambdaObs <= 0) return;

    // z = (lambdaObs - lambda0) / lambda0
    const z = (lambdaObs - lambda0) / lambda0;
    // Relativistic velocity: v/c = ((z+1)^2 - 1) / ((z+1)^2 + 1)
    const zPlus1Sq = Math.pow(z + 1, 2);
    const beta = (zPlus1Sq - 1) / (zPlus1Sq + 1);
    const vKms = beta * c;

    zEl.textContent = 'z = ' + z.toFixed(4);
    velEl.textContent = Math.round(vKms).toLocaleString() + ' km/s';
    cPctEl.textContent = (beta * 100).toFixed(2) + '% of c';
  }

  emitEl.addEventListener('input', update);
  obsEl.addEventListener('input', update);
  update();
})();

doppler-shift-frequency-velocity-radar-u.js:
(function() {
  'use strict';
  var slug = 'doppler-shift-frequency-velocity-radar-ultrasound-calculator';

  function el(id) {
    return document.getElementById(slug + '-' + id);
  }

  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');

  function setMsg(t, err) {
    msgEl.textContent = t;
    msgEl.classList.toggle('is-error', !!err);
  }

  function calculate() {
    try {

      var f0_ghz = parseFloat(el('freq-ghz').value);
      var v_kmh = parseFloat(el('velocity-kmh').value);
      var theta_deg = parseFloat(el('angle-deg').value);
      if (isNaN(f0_ghz) || f0_ghz <= 0 || isNaN(v_kmh) || isNaN(theta_deg)) {
        return { err: 'Please enter valid numerical values for carrier frequency, velocity, and angle.' };
      }
      var c = 3e8;
      var f0 = f0_ghz * 1e9;
      var v_ms = v_kmh / 3.6;
      var theta_rad = theta_deg * Math.PI / 180;
      var delta_f = (2 * v_ms * f0 * Math.cos(theta_rad)) / c;
      var out = 'RADAR & ULTRASOUND DOPPLER SHIFT ANALYSIS\n';
      out += '=========================================\n';
      out += 'Carrier Frequency (f0): ' + f0_ghz + ' GHz\n';
      out += 'Target Velocity (v)   : ' + v_kmh + ' km/h (' + v_ms.toFixed(2) + ' m/s)\n';
      out += 'Observation Angle (θ) : ' + theta_deg + '°\n\n';
      out += 'RESULTS:\n';
      out += 'Doppler Shift (Δf)    : ' + delta_f.toFixed(2) + ' Hz (' + (delta_f/1000).toFixed(4) + ' kHz)\n';
      out += 'Radial Velocity Component: ' + (v_ms * Math.cos(theta_rad)).toFixed(2) + ' m/s\n';
      out += 'Target Direction      : ' + (delta_f >= 0 ? 'Approaching (+ shift)' : 'Receding (- shift)');
      return { out: out, msg: 'Doppler frequency shift computed successfully.' };

    } catch(e) {
      return { err: 'Error during calculation: ' + e.message };
    }
  }

  btn.addEventListener('click', function() {
    var res = calculate();
    if (res.err) {
      outputEl.value = '';
      copyBtn.disabled = true;
      setMsg(res.err, true);
    } else {
      outputEl.value = res.out;
      copyBtn.disabled = false;
      setMsg(res.msg || 'Calculation completed successfully.');
    }
  });

  copyBtn.addEventListener('click', function() {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outputEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outputEl.value);
    }
    setMsg('Result copied to clipboard.');
  });

  clearBtn.addEventListener('click', function() {
    var inputs = ['freq-ghz', 'velocity-kmh', 'angle-deg'];
    inputs.forEach(function(id) {
      var elem = el(id);
      if (elem) elem.value = elem.defaultValue || '';
    });
    outputEl.value = '';
    copyBtn.disabled = true;
    setMsg('Cleared. Enter values above.');
  });
})();

download-time-calculator.js:
(() => {
  'use strict';
  const sizeEl = document.getElementById('dl-size');
  const sizeUnitEl = document.getElementById('dl-size-unit');
  const speedEl = document.getElementById('dl-speed');
  const speedUnitEl = document.getElementById('dl-speed-unit');

  const btn = document.getElementById('primary-action-btn');
  const clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message');
  const resCard = document.getElementById('dl-res-card');
  const resTime = document.getElementById('dl-res-time');
  const resRate = document.getElementById('dl-res-transfer-rate');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  function formatDuration(sec) {
    if (sec < 60) return Math.ceil(sec) + ' Seconds';
    const min = Math.floor(sec / 60);
    const s = Math.round(sec % 60);
    if (min < 60) return min + ' Min ' + s + ' Sec';
    const hr = Math.floor(min / 60);
    const m = min % 60;
    if (hr < 24) return hr + ' Hours ' + m + ' Min';
    const days = Math.floor(hr / 24);
    const h = hr % 24;
    return days + ' Days ' + h + ' Hours';
  }

  btn.addEventListener('click', () => {
    const size = parseFloat(sizeEl.value);
    const speed = parseFloat(speedEl.value);

    if (isNaN(size) || isNaN(speed) || size <= 0 || speed <= 0) {
      setMsg('Please enter valid positive numbers for file size and connection speed.', true);
      resCard.style.display = 'none';
      return;
    }

    // Convert file size to MegaBytes (MB)
    let sizeMB = size;
    if (sizeUnitEl.value === 'GB') sizeMB = size * 1024;
    else if (sizeUnitEl.value === 'TB') sizeMB = size * 1024 * 1024;

    // Convert speed to MegaBytes per second (MB/s)
    let speedMBps = speed;
    if (speedUnitEl.value === 'Mbps') speedMBps = speed / 8;
    else if (speedUnitEl.value === 'Gbps') speedMBps = (speed * 1000) / 8;

    const totalSeconds = sizeMB / speedMBps;

    resTime.textContent = formatDuration(totalSeconds);
    resRate.textContent = speedMBps.toFixed(2) + ' MB/s';

    resCard.style.display = 'block';
    setMsg('Download duration calculated.');
  });

  clearBtn.addEventListener('click', () => {
    sizeEl.value = ''; speedEl.value = ''; resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

