      if (b === 0) { setMsg('Resistance cannot be zero.', true); return; }
      p = (a * a) / b;
      out = 'Formula: P = V^2 / R\nV = ' + a + ' V, R = ' + b + ' ohm\nPower P = ' + p.toFixed(4) + ' W';
