  function update() {
    const Q = parseFloat(qEl.value), fc = parseFloat(fcEl.value);
    if (isNaN(Q) || isNaN(fc) || Q <= 0 || fc <= 0) return;

    // N (octaves) = (2 / ln(2)) * asinh(1 / (2*Q))
