      var dr = parseFloat(el('data-rate-gbps').value);
      var tj = parseFloat(el('tj-ps').value);
      var eh = parseFloat(el('eye-height-mv').value);
      if (isNaN(dr) || dr <= 0 || isNaN(tj) || tj < 0 || isNaN(eh) || eh <= 0) {
