    if (wave === 'square') {
      // Square wave: b_n = (4 * A) / (n * pi) for odd n
      b1 = (4.0 * A) / (1.0 * Math.PI);
      b3 = (4.0 * A) / (3.0 * Math.PI);
      b5 = (4.0 * A) / (5.0 * Math.PI);
      formula = 'f(t) = ' + b1.toFixed(2) + '·sin(ωt) + ' + b3.toFixed(2) + '·sin(3ωt) + ' + b5.toFixed(2) + '·sin(5ωt)';
