    } else if (wave === 'sawtooth') {
      // Sawtooth: b_n = (2 * A) / (n * pi) * (-1)^(n+1)
      b1 = (2.0 * A) / (1.0 * Math.PI);
      b3 = (2.0 * A) / (2.0 * Math.PI);
      b5 = (2.0 * A) / (3.0 * Math.PI);
      formula = 'f(t) = ' + b1.toFixed(2) + '·sin(ωt) - ' + b3.toFixed(2) + '·sin(2ωt) + ' + b5.toFixed(2) + '·sin(3ωt)';
