gas-absorption-kremser-equation-stages-c.js:
(() => {
  'use strict';
  const yinEl = document.getElementById('krm-yin'), youtEl = document.getElementById('krm-yout');
  const lgEl = document.getElementById('krm-lg'), mEl = document.getElementById('krm-m');
  const nResEl = document.getElementById('krm-res-n'), aResEl = document.getElementById('krm-res-a');

  function update() {
    const yinPct = parseFloat(yinEl.value), youtPct = parseFloat(youtEl.value);
    const LG = parseFloat(lgEl.value), m = parseFloat(mEl.value);

    if (isNaN(yinPct) || isNaN(youtPct) || isNaN(LG) || isNaN(m) || yinPct <= youtPct || youtPct <= 0 || LG <= 0 || m <= 0) return;

    // Absorption factor A = L / (m * G) = (L/G) / m
    const A = LG / m;

    const removalPct = ((yinPct - youtPct) / yinPct) * 100;

    let N = 0;
    if (Math.abs(A - 1.0) < 0.01) {
      // Special case A = 1: N = (yin - yout) / yout
      N = (yinPct - youtPct) / youtPct;
    } else {
      // Kremser absorption formula with clean solvent (x_in = 0):
      // N = ln( (1 - 1/A)*(yin / yout) + 1/A ) / ln(A)
      const term = ((1.0 - (1.0 / A)) * (yinPct / youtPct)) + (1.0 / A);
      if (term > 0) {
        N = Math.log(term) / Math.log(A);
      } else {
        nResEl.textContent = 'Absorption Factor Too Low (A < 1)';
        return;
      }
    }

    nResEl.textContent = 'N = ' + N.toFixed(2) + ' Stages (' + Math.ceil(N) + ' Theoretical Trays)';
    aResEl.textContent = 'Absorption Factor A = ' + A.toFixed(2) + ' (' + removalPct.toFixed(1) + '% Solute Scrubbed | L/G = ' + LG.toFixed(2) + ', m = ' + m.toFixed(2) + ')';
  }

  [yinEl, youtEl, lgEl, mEl].forEach(el => el.addEventListener('input', update));
  update();
})();

gas-compressibility-z-factor-hall-yarbor.js:
(() => {
  'use strict';
  const pEl = document.getElementById('z-ppr'), tEl = document.getElementById('z-tpr');
  const zResEl = document.getElementById('z-res-val'), dResEl = document.getElementById('z-res-dens');

  function update() {
    const Ppr = parseFloat(pEl.value), Tpr = parseFloat(tEl.value);
    if (isNaN(Ppr) || isNaN(Tpr) || Ppr <= 0 || Tpr <= 1.0) return;

    // Hall-Yarborough / Beggs-Brill analytical fit for Z-factor:
    // A = 1.39 * (Tpr - 0.92)^0.5 - 0.36 * Tpr - 0.10
    // B = (0.62 - 0.23*Tpr)*Ppr + ( (0.066 / (Tpr - 0.86)) - 0.037 ) * Ppr^2 + 0.32 * Ppr^6 / 10^(9*(Tpr-1))
    // C = 0.132 - 0.32*log10(Tpr)
    // D = 10^(0.3106 - 0.49*Tpr + 0.1824*Tpr^2)
    // Z = A + (1 - A) / exp(B) + C * Ppr^D
    const A = (1.39 * Math.pow(Math.max(0.01, Tpr - 0.92), 0.5)) - (0.36 * Tpr) - 0.10;
    const termB1 = (0.62 - (0.23 * Tpr)) * Ppr;
    const termB2 = ((0.066 / Math.max(0.01, Tpr - 0.86)) - 0.037) * Math.pow(Ppr, 2);
    const termB3 = (0.32 * Math.pow(Ppr, 6)) / Math.pow(10, 9 * (Tpr - 1));
    const B = termB1 + termB2 + termB3;
    const C = 0.132 - (0.32 * Math.log10(Tpr));
    const D = Math.pow(10, 0.3106 - (0.49 * Tpr) + (0.1824 * Math.pow(Tpr, 2)));

    const Z = A + ((1 - A) / Math.exp(Math.max(-50, Math.min(50, B)))) + (C * Math.pow(Ppr, D));

    zResEl.textContent = 'Z = ' + Z.toFixed(3) + ' (Real Gas Z-Factor)';
    dResEl.textContent = 'Compressibility: ' + (Z * 100).toFixed(1) + '% of Ideal Volume (Gas Expansion Factor B_g ∝ Z·T/P)';
  }

  pEl.addEventListener('input', update);
  tEl.addEventListener('input', update);
  update();
})();

