(() => {
  'use strict';
  const kEl = document.getElementById('gd-k'), muEl = document.getElementById('gd-mu');
  const dEl = document.getElementById('gd-d'), tEl = document.getElementById('gd-t'), rtEl = document.getElementById('gd-ratio');
  const lResEl = document.getElementById('gd-res-l'), alResEl = document.getElementById('gd-res-alpha');

  function update() {
    const K = parseFloat(kEl.value), mu = parseFloat(muEl.value);
    const d = parseFloat(dEl.value), t = parseFloat(tEl.value), ratio = parseFloat(rtEl.value);

    if (isNaN(K) || isNaN(mu) || isNaN(d) || isNaN(t) || isNaN(ratio) || K <= 0 || mu <= 0 || d <= 0 || t <= 0 || ratio <= 0 || ratio >= 1) return;

    // Glover-Dumm equation: h_t / h_0 = ( 4 / pi ) * exp( - alpha * t )
    // alpha = ( 1 / t ) * ln( (4 / pi) / (h_t / h_0) )
    const alpha = (1.0 / t) * Math.log((4.0 / Math.PI) / ratio);
    if (alpha <= 0) return;

    // alpha = ( pi^2 * K * d ) / ( mu * L^2 ) => L = sqrt( (pi^2 * K * d) / (mu * alpha) )
    const L = Math.sqrt((Math.pow(Math.PI, 2) * K * d) / (mu * alpha));

    lResEl.textContent = 'Drain Spacing L = ' + L.toFixed(1) + ' m';
    alResEl.textContent = 'Reaction Factor α = ' + alpha.toFixed(3) + ' day⁻¹ | ' + (ratio * 100).toFixed(0) + '% drop in ' + t + ' days (K=' + K + ' m/day, d=' + d + ' m)';
  }

  [kEl, muEl, dEl, tEl, rtEl].forEach(el => el.addEventListener('input', update));
  update();
})();

goldman-hodgkin-katz-ghk-membrane-potent.js:
(() => {
  'use strict';
  const koEl = document.getElementById('ghk-ko'), kiEl = document.getElementById('ghk-ki');
  const naoEl = document.getElementById('ghk-nao'), naiEl = document.getElementById('ghk-nai'), pnaEl = document.getElementById('ghk-pna');
  const vmResEl = document.getElementById('ghk-res-vm'), nrResEl = document.getElementById('ghk-res-nernst');

  const R = 8.314462;
  const F = 96485.33;
  const T = 310.15; // 37°C in Kelvin
  const RT_F_mV = (R * T / F) * 1000; // ~26.7 mV (ln multiplier: 61.5 for log10)

  // Standard chloride concentrations:
  const clo = 110.0;
  const cli = 10.0;
  const P_Cl = 0.40;

  function update() {
    const Ko = parseFloat(koEl.value), Ki = parseFloat(kiEl.value);
    const Nao = parseFloat(naoEl.value), Nai = parseFloat(naiEl.value);
    const P_Na = parseFloat(pnaEl.value);

    if (isNaN(Ko) || isNaN(Ki) || isNaN(Nao) || isNaN(Nai) || isNaN(P_Na) || Ko <= 0 || Ki <= 0 || Nao <= 0 || Nai <= 0 || P_Na < 0) return;

    const P_K = 1.00;

    // GHK Voltage equation: Vm = (RT/F) * ln( (P_K*Ko + P_Na*Nao + P_Cl*Cli) / (P_K*Ki + P_Na*Nai + P_Cl*Clo) )  [mV]
    const num = (P_K * Ko) + (P_Na * Nao) + (P_Cl * cli);
    const den = (P_K * Ki) + (P_Na * Nai) + (P_Cl * clo);
    const Vm = RT_F_mV * Math.log(num / den);

    // Individual Nernst potentials:
    const E_K = RT_F_mV * Math.log(Ko / Ki);
    const E_Na = RT_F_mV * Math.log(Nao / Nai);
    const E_Cl = -RT_F_mV * Math.log(clo / cli); // negative valence

    vmResEl.textContent = 'V_m = ' + Vm.toFixed(1) + ' mV Resting Potential';
    nrResEl.textContent = 'Nernst: E_K = ' + E_K.toFixed(1) + ' mV | E_Na = +' + E_Na.toFixed(1) + ' mV | E_Cl = ' + E_Cl.toFixed(1) + ' mV (RT/F = ' + RT_F_mV.toFixed(1) + ' mV @ 37°C)';
  }

  [koEl, kiEl, naoEl, naiEl, pnaEl].forEach(el => el.addEventListener('input', update));
  update();
})();

goodman-soderberg-gerber-fatigue-enduran.js:
(() => {
  'use strict';
  const saEl = document.getElementById('gm-sa'), smEl = document.getElementById('gm-sm');
  const seEl = document.getElementById('gm-se'), sutEl = document.getElementById('gm-sut');
  const gdResEl = document.getElementById('gm-res-goodman'), cpResEl = document.getElementById('gm-res-comp');

  function update() {
    const sigma_a = parseFloat(saEl.value), sigma_m = parseFloat(smEl.value);
    const Se = parseFloat(seEl.value), Sut = parseFloat(sutEl.value);

    if (isNaN(sigma_a) || isNaN(sigma_m) || isNaN(Se) || isNaN(Sut) || sigma_a < 0 || Se <= 0 || Sut <= 0) return;

    // Modified Goodman factor: 1 / n = (sigma_a / Se) + (sigma_m / Sut)
    const goodman_denom = (sigma_a / Se) + (sigma_m / Sut);
    const n_goodman = goodman_denom > 0 ? 1.0 / goodman_denom : 1.0;

    // Soderberg factor using Sy approx 0.8 * Sut:
    const Sy = 0.8 * Sut;
    const soderberg_denom = (sigma_a / Se) + (sigma_m / Sy);
    const n_soderberg = soderberg_denom > 0 ? 1.0 / soderberg_denom : 1.0;

    // Gerber factor: 1/n = (sigma_a / Se) + (sigma_m / Sut)^2 -> Solve quadratic for n:
    // n * (sigma_a / Se) + n^2 * (sigma_m / Sut)^2 = 1
    let n_gerber = 1.0;
    const A = Math.pow(sigma_m / Sut, 2);
    const B = sigma_a / Se;
    if (A > 0) {
      n_gerber = (-B + Math.sqrt(Math.pow(B, 2) + 4.0 * A)) / (2.0 * A);
    } else if (B > 0) {
      n_gerber = 1.0 / B;
    }

    gdResEl.textContent = 'Goodman Factor N = ' + n_goodman.toFixed(2) + ' (' + (n_goodman >= 1.0 ? 'SAFE ✓' : 'FATIGUE FAILURE ✗') + ')';
    gdResEl.style.color = n_goodman >= 1.0 ? '#22543d' : '#c53030';
    cpResEl.textContent = 'Gerber N = ' + n_gerber.toFixed(2) + ' | Soderberg N = ' + n_soderberg.toFixed(2) + ' (σ_a = ' + sigma_a + ' MPa, σ_m = ' + sigma_m + ' MPa)';
  }

  [saEl, smEl, seEl, sutEl].forEach(el => el.addEventListener('input', update));
  update();
})();

