  const fResEl = document.getElementById('wr-res-flow'), mResEl = document.getElementById('wr-res-m3h');

  const g = 9.80665;

  function update() {
    const H_cm = parseFloat(hEl.value), thDeg = parseFloat(thEl.value), Cd = parseFloat(cdEl.value);
