    const Q_gpm = Q_lps * 15.8503;
    const Q_m3_h = Q_m3_s * 3600.0;

    fResEl.textContent = 'Q = ' + Q_lps.toFixed(2) + ' L / s (' + Q_gpm.toFixed(1) + ' GPM)';
    mResEl.textContent = 'Q = ' + Q_m3_h.toFixed(1) + ' m³/h (' + thDeg + '° V-Notch @ H = ' + H_cm + ' cm, C_d = ' + Cd + ')';
