gravitational-wave-strain-orbital-decay-.js:
(() => {
  'use strict';
  const m1El = document.getElementById('gw-m1'), m2El = document.getElementById('gw-m2'), fEl = document.getElementById('gw-f');
  const mcResEl = document.getElementById('gw-res-mchirp'), dfResEl = document.getElementById('gw-res-dfdt');

  const G = 6.67430e-11;
  const c = 299792458;
  const M_sun_kg = 1.98847e30;

  function update() {
    const m1 = parseFloat(m1El.value), m2 = parseFloat(m2El.value), f_gw = parseFloat(fEl.value);
    if (isNaN(m1) || isNaN(m2) || isNaN(f_gw) || m1 <= 0 || m2 <= 0 || f_gw <= 0) return;

    // Chirp mass M_chirp = (m1 * m2)^(3/5) / (m1 + m2)^(1/5)  [Solar masses]
    const M_chirp_solar = Math.pow(m1 * m2, 0.6) / Math.pow(m1 + m2, 0.2);
    const M_chirp_kg = M_chirp_solar * M_sun_kg;

    // Frequency chirp rate df/dt:
    // df/dt = (96/5) * pi^(8/3) * ( (G * M_chirp) / c^3 )^(5/3) * f^(11/3)  [Hz / s]
    const geomFactor = (G * M_chirp_kg) / Math.pow(c, 3);
    const df_dt = (96.0 / 5.0) * Math.pow(Math.PI, 8.0/3.0) * Math.pow(geomFactor, 5.0/3.0) * Math.pow(f_gw, 11.0/3.0);

    // Time to merger tau_merge = (5/256) * ( c^3 / (G * M_chirp) )^(5/3) * ( pi * f_gw )^(-8/3)  [seconds]
    const tau_merge_sec = (5.0 / 256.0) * Math.pow(geomFactor, -5.0/3.0) * Math.pow(Math.PI * f_gw, -8.0/3.0);
    const tau_merge_ms = tau_merge_sec * 1000.0;

    mcResEl.textContent = 'ℳ = ' + M_chirp_solar.toFixed(2) + ' M_☉ (Total M = ' + (m1 + m2).toFixed(1) + ' M_☉)';
    dfResEl.textContent = 'Chirp df/dt = +' + Math.round(df_dt).toLocaleString() + ' Hz/s | Time to Merger: ' + (tau_merge_ms < 1000 ? tau_merge_ms.toFixed(1) + ' ms' : tau_merge_sec.toFixed(2) + ' s') + ' @ ' + f_gw + ' Hz';
  }

  [m1El, m2El, fEl].forEach(el => el.addEventListener('input', update));
  update();
})();

gravity-gradient-torque-spacecraft-attit.js:
(() => {
  'use strict';
  const diEl = document.getElementById('gg-di'), thEl = document.getElementById('gg-theta'), altEl = document.getElementById('gg-alt');
  const tgResEl = document.getElementById('gg-res-tgg'), stResEl = document.getElementById('gg-res-stab');

  const mu_earth = 398600.4418;
  const R_earth = 6378.137;

  function update() {
    const delta_I = parseFloat(diEl.value), theta_deg = parseFloat(thEl.value), h_km = parseFloat(altEl.value);
    if (isNaN(delta_I) || isNaN(theta_deg) || isNaN(h_km) || delta_I <= 0 || h_km < 0) return;

    const r_km = R_earth + h_km;
    const theta_rad = (theta_deg * Math.PI) / 180.0;
    const omega0 = Math.sqrt(mu_earth / Math.pow(r_km, 3));
    const Period_min = (2.0 * Math.PI / omega0) / 60.0;
    const T_GG_Nm = 1.5 * Math.pow(omega0, 2) * delta_I * Math.sin(2.0 * theta_rad);
    const T_GG_uNm = T_GG_Nm * 1e6;

    tgResEl.textContent = 'Restoring Torque T_GG = ' + T_GG_uNm.toFixed(1) + ' μN · m (' + T_GG_Nm.toExponential(2) + ' N·m)';
    stResEl.textContent = 'Passive Nadir Lock Active (ω₀ = ' + (omega0*1000).toFixed(3) + ' mrad/s, Orbit Period T = ' + Period_min.toFixed(1) + ' min @ h=' + h_km + ' km)';
  }

  [diEl, thEl, altEl].forEach(el => el.addEventListener('input', update));
  update();
})();

gravity-turn-rocket-launch-pitchover-tra.js:
(() => {
  'use strict';
  const vEl = document.getElementById('gt-v'), gEl = document.getElementById('gt-gamma'), aEl = document.getElementById('gt-alt');
  const gdResEl = document.getElementById('gt-res-gdot'), grResEl = document.getElementById('gt-res-grav');

  const g0 = 9.80665;
  const R_E = 6378.137; // km

  function update() {
    const v = parseFloat(vEl.value), gammaDeg = parseFloat(gEl.value), hKm = parseFloat(aEl.value);
    if (isNaN(v) || isNaN(gammaDeg) || isNaN(hKm) || v <= 0 || gammaDeg <= 0 || gammaDeg > 90 || hKm < 0) return;

    const r_km = R_E + hKm;
    const r_m = r_km * 1000.0;

    // Altitude-dependent local gravity g = g0 * (R_E / r)^2
    const g_local = g0 * Math.pow(R_E / r_km, 2);

    const gammaRad = (gammaDeg * Math.PI) / 180;

    // Gravity turn flight path rate: gamma_dot = - (g_local / v) * cos(gamma) + (v / r_m) * cos(gamma)  [rad / s]
    const gamma_dot_rad = (-(g_local / v) + (v / r_m)) * Math.cos(gammaRad);
    const gamma_dot_deg = (gamma_dot_rad * 180.0) / Math.PI;

    // Instantaneous gravity drag loss a_grav = g_local * sin(gamma)  [m / s^2]
    const a_grav = g_local * Math.sin(gammaRad);

    gdResEl.textContent = 'γ̇ = ' + gamma_dot_deg.toFixed(3) + ' ° / second (Pitching Down)';
    grResEl.textContent = 'Gravity Drag: ' + a_grav.toFixed(2) + ' m/s² (g_local = ' + g_local.toFixed(2) + ' m/s² @ h = ' + hKm + ' km, v = ' + v + ' m/s)';
  }

  [vEl, gEl, aEl].forEach(el => el.addEventListener('input', update));
  update();
})();

great-circle-haversine-distance-bearing-.js:
(() => {
  'use strict';
  const lat1El = document.getElementById('hav-lat1'), lon1El = document.getElementById('hav-lon1');
  const lat2El = document.getElementById('hav-lat2'), lon2El = document.getElementById('hav-lon2');
  const dResEl = document.getElementById('hav-res-dist'), bResEl = document.getElementById('hav-res-brg');

  const R_earth = 6371.0; // Mean Earth radius in km

  function update() {
    const lat1 = parseFloat(lat1El.value), lon1 = parseFloat(lon1El.value);
    const lat2 = parseFloat(lat2El.value), lon2 = parseFloat(lon2El.value);

    if (isNaN(lat1) || isNaN(lon1) || isNaN(lat2) || isNaN(lon2)) return;

    const phi1 = (lat1 * Math.PI) / 180;
    const phi2 = (lat2 * Math.PI) / 180;
    const deltaPhi = ((lat2 - lat1) * Math.PI) / 180;
    const deltaLam = ((lon2 - lon1) * Math.PI) / 180;

    // Haversine formula:
    // a = sin^2(dPhi/2) + cos(phi1)*cos(phi2)*sin^2(dLam/2)
    // c = 2 * atan2( sqrt(a), sqrt(1-a) )
    const a = Math.pow(Math.sin(deltaPhi / 2), 2) + (Math.cos(phi1) * Math.cos(phi2) * Math.pow(Math.sin(deltaLam / 2), 2));
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const distKm = R_earth * c;
    const distNm = distKm * 0.539957;
    const distMiles = distKm * 0.621371;

    // Initial bearing theta = atan2( sin(dLam)*cos(phi2), cos(phi1)*sin(phi2) - sin(phi1)*cos(phi2)*cos(dLam) )
    const y = Math.sin(deltaLam) * Math.cos(phi2);
    const x = (Math.cos(phi1) * Math.sin(phi2)) - (Math.sin(phi1) * Math.cos(phi2) * Math.cos(deltaLam));
    let brgDeg = (Math.atan2(y, x) * 180) / Math.PI;
    brgDeg = (brgDeg + 360) % 360; // normalize to 0-360°

    dResEl.textContent = Math.round(distKm).toLocaleString() + ' km (' + Math.round(distNm).toLocaleString() + ' NM / ' + Math.round(distMiles).toLocaleString() + ' Miles)';
    bResEl.textContent = 'Initial Heading: ' + brgDeg.toFixed(1) + '° True Azimuth (Great Circle Arc)';
  }

  [lat1El, lon1El, lat2El, lon2El].forEach(el => el.addEventListener('input', update));
  update();
})();
